pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, address(caller).balance);

        uint balanceBefore = c.getBalance(caller);

        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));

        if (success) {
            uint balanceAfter = c.getBalance(caller);
            assertTrue(balanceAfter == balanceBefore + amount, "Balance should increase by the sent amount");
        }
    }
}

