pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 0, address(c).balance + 1e30); // limit to avoid overflow in expected addition
        uint256 initialBalance = c.getBalance(sender);
        uint256 initialContractBalance = address(c).balance;
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.addToBalance.selector));
        assertTrue(success, "call failed");
        uint256 finalBalance = c.getBalance(sender);
        assertTrue(finalBalance == initialBalance + amount, "balance not increased by amount");
    }
}

